UISmokeEmitter=function(game,targetSprite){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,15);this.targetSprite=targetSprite;this.particleClass=UISmokeParticle;this.makeParticles('game',['smoke0','smoke1','smoke2']);this.minParticleSpeed.setTo(-40,-40);this.maxParticleSpeed.setTo(40,40);this.particleDrag.setTo(50,50);this.setAlpha(0.85,1.0);this.setRotation(0,0);this.minParticleScale=UIConstants.GAME_ASSET_SCALE*0.66;this.maxParticleScale=UIConstants.GAME_ASSET_SCALE*1.0;this.gravity=0;this.kill();this.visible=false;};UISmokeEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UISmokeEmitter.prototype.constructor=UISmokeEmitter;UISmokeEmitter.prototype.preUpdate=function(){if(!this.exists||this.game.physics.arcade.isPaused){return false;}return Phaser.Particles.Arcade.Emitter.prototype.preUpdate.call(this);};UISmokeEmitter.prototype.update=function(){if(!this.exists||this.game.physics.arcade.isPaused){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);this.x=this.targetSprite.x;this.y=this.targetSprite.y;if(this.on&&!this.targetSprite.exists){this.on=false;}else if(this.on&&this.targetSprite.exists&&this.targetSprite.alpha<1.0){this.setAlpha(0.85*this.targetSprite.alpha,1.0*this.targetSprite.alpha);}if(this.countLiving()==0){this.kill();this.visible=false;}};UISmokeEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UISmokeEmitter.prototype.spawn=function(x,y){this.revive();this.visible=true;this.x=x;this.y=y;this.setAlpha(0.85,1.0);this.explode(2000,1);this.start(false,2000,134,0,false);};UISmokeEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};